import{z as B,x as s,o as i,c as A,q as l,j as p,D as e,d as r,s as n,S as o,b as E}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"合谋与卡特尔","description":"","frontmatter":{"title":"合谋与卡特尔","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/collusion-cartel.md","filePath":"econ/collusion-cartel.md","lastUpdated":1791413859000}'),d={name:"econ/collusion-cartel.md"};function m(c,a,_,C,F,h){const t=s("Mermaid");return i(),A("div",null,[a[2]||(a[2]=l('<h1 id="合谋与卡特尔" tabindex="-1">合谋与卡特尔 <a class="header-anchor" href="#合谋与卡特尔" aria-label="Permalink to &quot;合谋与卡特尔&quot;">​</a></h1><div class="epigraph"><p>秘密降价的诱惑随买家数目与监测难度上升；静态伯川德把垄断价喊碎，重复互动才可能把它撑住。</p><footer>—— 据 Stigler, A Theory of Oligopoly, JPE, 1964；Friedman, A Non-cooperative Equilibrium for Supergames, RES, 1971 整理</footer></div><p>定位：<a href="/econ/bertrand-capacity">上一课</a>。同质、产能无限时同时喊价落到 \\(P=\\mathrm{MC}\\)；产能预承诺可以把产量读回古诺。本课不重讲配给规则与 Kreps–Scheinkman。缺口是：静态博弈里垄断价不是相互最优，卡特尔协议在一次性伯川德里不可自我实施。要把垄断价撑住，必须换时间结构——接到<a href="/econ/folk-theorem">重复博弈</a>，本课只写产业组织这一侧。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>卡特尔想实施垄断产量 \\(Q_m\\) 与价格 \\(P_m\\)，再按配额分 \\(\\pi_m\\)。静态里每家的最优偏离是：别人守约时，自己略微底切（伯川德）或把自己的产量扩到剩余需求的 \\(\\mathrm{MR}=\\mathrm{MC}\\)（古诺）。利润从份额变成几乎整块垄断剩余，一次性没有惩罚，合谋崩溃。缺口不是再定义一次 MR，而是：<strong>静态无法维持 \\(P_m\\)，维持需要可置信的未来损失。</strong></p><p>Stigler 把秘密降价写成信息不对称：卖方看不见对方的成交价，只看见自己的销量波动。买家越多、订单越碎，把降价伪装成需求冲击越容易，合谋越脆。这是监测问题，与无名氏定理的完美监测上界对照。</p><p><span class="marginnote">直觉类比：卡特尔像几个加油站约好统一高价。白天互相盯着还行；一到夜里，某家偷偷给熟客打九折——别人只见自己客流变少，分不清是对方作弊还是生意淡季。看得见背叛，威慑才成立；看不清，约好高价就守不住。</span></p><h3 id="卡特尔不是另一家垄断者" tabindex="-1">卡特尔不是另一家垄断者 <a class="header-anchor" href="#卡特尔不是另一家垄断者" aria-label="Permalink to &quot;卡特尔不是另一家垄断者&quot;">​</a></h3><p>把 \\(n\\) 家加总当成一家去读勒纳，漏掉激励相容。配额、补偿支付、共同销售机构，都是为了改偏离收益；没有这些，联合利润最大化只是规划，不是均衡。产能约束可以帮忙：打满的工厂底切空间小，合谋更容易——与上一课「产能把伯川德接回古诺」是同一把刀，方向变成「产能也挡住偏离」。</p><p><span class="marginnote">Friedman 的纳什回归：合作路径上要 \\(P_m\\)，一旦观测到偏离，永远回到阶段纳什（伯川德则是 \\(P=\\mathrm{MC}\\)）。贴现 \\(\\delta\\) 够大时，未来损失压过当期底切。本课不把无名氏集合整段搬来，只钉这一触发。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>阶段博弈取伯川德或古诺。合作支付 \\(\\pi_c\\)，偏离 \\(\\pi_d\\)，惩罚支付 \\(\\pi_p\\)（常取阶段纳什）。激励相容：</p> \\[\\pi_d-\\pi_c\\le\\frac{\\delta}{1-\\delta}(\\pi_c-\\pi_p). \\]<p>\\(\\delta\\) 越大、 \\((\\pi_c-\\pi_p)\\) 越大、当期偏离增益越小，合谋越容易。\\(n\\) 增加通常摊薄 \\(\\pi_c\\)、放大 \\(\\pi_d\\) 的相对诱惑。需求繁荣抬高当期偏离收益，Rotemberg–Saloner 一类比较静态说繁荣期更难合谋——声明监测假设后再用。</p><p><span class="marginnote">数字实例：一次性偏离多赚 \\(\\pi_d-\\pi_c=50\\)，被罚后每期少赚 \\(\\pi_c-\\pi_p=10\\)。要压住偏离，需 \\(\\frac{\\delta}{1-\\delta}\\times 10\\ge 50\\)，即 \\(\\delta\\ge 5/6\\approx 0.83\\)——只有足够看重未来，惩罚才够痛。\\(\\delta\\) 从 0.9 降到 0.7，同一个卡特尔就从可行变成崩盘。</span></p><p>公开价格、同质大单、行业协会的信息交换，都是把监测从噪声里捞出来。本课不写反托拉斯条文，只写激励。</p>',16)),(i(),p(o,null,{default:e(()=>[n(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20STAT%5B%22%E9%9D%99%E6%80%81%E4%BC%AF%E5%B7%9D%E5%BE%B7%EF%BC%9AP%20%3D%20MC%22%5D%20--%3E%20DEV%5B%22%E5%AE%88%E7%BA%A6%E6%97%B6%E5%BA%95%E5%88%87%E6%9C%80%E6%9C%89%E5%88%A9%22%5D%0A%20%20DEV%20--%3E%20REP%5B%22%E9%87%8D%E5%A4%8D%20%2B%20%E8%A7%A6%E5%8F%91%E6%83%A9%E7%BD%9A%22%5D%0A%20%20REP%20--%3E%20IC%5B%22%CE%B4%20%E5%A4%A7%EF%BC%9AP_m%20%E5%8F%AF%E5%AE%9E%E6%96%BD%22%5D%0A%20%20IC%20--%3E%20MON%5B%22%E7%9B%91%E6%B5%8B%E5%B7%AE%EF%BC%9A%E7%A7%98%E5%AF%86%E9%99%8D%E4%BB%B7%EF%BC%8C%E9%9B%86%E5%90%88%E6%94%B6%E7%BC%A9%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"不要把「惩罚」写成限价簿上的掠夺性挂单；这里是产品市场的重复定价，没有时间优先队列。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"自我实施的机制是贴现：偏离赚一次 \\(\\pi_d-\\pi_c\\)，之后每期少赚 \\(\\pi_c-\\pi_p\\)。产能与差异改变的是 \\(\\pi_d\\)：差异越大，底切抢不到全部需求，偏离变钝，合谋可以更松——但差异也降低 \\(P_m\\) 相对竞争的升水，净效应要算。秘密降价的机制是信号提取：观测不到对方的 \\(p\\)，只能对销量做假设检验，惩罚会误伤，于是均衡必须掺噪声、效率下降。",-1)),(i(),p(o,null,{default:e(()=>[n(t,{id:"mermaid-54",class:"mermaid",graph:"flowchart%20LR%0A%20%20COOP%5B%22%E5%AE%88%E7%BA%A6%E8%B7%AF%E5%BE%84%EF%BC%9A%E6%AF%8F%E6%9C%9F%E5%88%86%20%CF%80c%22%5D%20--%3E%20TEMPT%5B%22%E5%BD%93%E6%9C%9F%E5%81%8F%E7%A6%BB%EF%BC%9A%E7%8B%AC%E5%90%9E%20%CF%80d%22%5D%0A%20%20TEMPT%20--%3E%20TRIG%5B%22%E8%A2%AB%E8%A7%82%E6%B5%8B%E5%88%B0%EF%BC%9A%E6%B0%B8%E8%BF%9C%E5%9B%9E%E9%98%B6%E6%AE%B5%E7%BA%B3%E4%BB%80%20%CF%80p%22%5D%0A%20%20TRIG%20--%3E%20LOSS%5B%22%E6%9C%AA%E6%9D%A5%E6%AF%8F%E6%9C%9F%E5%B0%91%E8%B5%9A%20%CF%80c%20%E2%88%92%20%CF%80p%EF%BC%8C%E6%97%A0%E9%99%90%E6%9C%9F%E7%B4%AF%E8%AE%A1%22%5D%0A%20%20LOSS%20--%3E%20CMP%7B%22%E8%B4%B4%E7%8E%B0%E5%90%8E%E6%8D%9F%E5%A4%B1%20%E2%89%A5%20%E4%B8%80%E6%AC%A1%E6%94%B6%E7%9B%8A%EF%BC%9F%22%7D%0A%20%20CMP%20--%3E%7C%E6%98%AF%7C%20STAY%5B%22%E4%B8%8D%E5%81%8F%E7%A6%BB%EF%BC%9AP_m%20%E6%92%91%E5%BE%97%E4%BD%8F%22%5D%0A%20%20CMP%20--%3E%7C%E5%90%A6%7C%20BREAK%5B%22%E5%81%8F%E7%A6%BB%EF%BC%9A%E5%90%88%E8%B0%8B%E5%B4%A9%E5%9B%9E%E4%BB%B7%E6%A0%BC%E6%88%98%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p><span class="marginnote">术语翻译：触发策略就是「一次不忠、百次不用」——只要你没被抓到，大家继续分垄断利润；一旦观测到你底切，从此每期都回到竞争价，谁也不再理你。它可怕之处在于零宽容：哪怕误判一次也会引爆价格战，这正是后面「监测掺噪声」问题的根源。</span></p><p>与斯塔克尔伯格无关：合谋是对称的重复，不是先动承诺。指定一家「领导报价」若可观测、可惩罚，只是合谋的交流装置，不要写成<a href="/econ/stackelberg">产量领导</a>的反应曲线切点。</p><p>产能的另一面：过剩产能使惩罚更狠（偏离后可以立刻扩产砸价），也使当期偏离更诱人。经验上「过剩产能支撑卡特尔」不是定理，要看惩罚与偏离哪一头升得更快。产品同质、公开报价、买方集中，Stigler 的监测更易；碎买家、秘密折扣，触发策略的观测失败，无名氏集合收缩。</p><p><span class="marginnote">Stigler 1964 强调买方侧的信息结构，不是博弈论触发策略。Friedman 1971 才把超博弈均衡写清楚。两篇合在一起：激励相容加监测。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>有限次重复、阶段纳什唯一时，逆向归纳钉死竞争；有限次要合谋，需要阶段有多个纳什或声誉。反垄断的宽赦、私人诉讼改变 \\(\\pi_d\\) 的法律期望，本课不写。后课<a href="/econ/limit-pricing">限制进入定价</a>对付的是潜在进入者，不是在位者之间的配额。</p><p><span class="marginnote">常见误区：以为「反正还要长期打交道」就足以撑起合谋。若互动有确定的最后一期，倒推归纳会从末局开始拆：最后一期背叛零成本 → 倒数第二期也没人守约 → 一路拆回第一期，价格战提前上演。现实中合同到期前的服务质量下滑、老客户被「最后宰一刀」，就是同一机制的影子。</span></p><p>后课默认：静态伯川德（或古诺）撑不住卡特尔；重复加监测才可能。无名氏定理给出可能性，不给出哪一个卡特尔会被选中。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>静态价格战把 \\(P_m\\) 底切掉；合谋是重复博弈的激励相容。</li><li>监测越差、买家越碎，秘密降价越容易，卡特尔越脆。</li><li>产能与差异改偏离收益，不改「需要未来惩罚」这一层。</li><li>下一课让一家先动，把同时选择改成可观察的产量承诺。</li><li>出处：Stigler, <em>JPE</em>, 1964；Friedman, <em>RES</em>, 1971。</li></ul>',10))])}const f=B(d,[["render",m]]);export{P as __pageData,f as default};
